DROP TABLE IF EXISTS `outbox_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `outbox_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_id` binary(16) NOT NULL,
  `institution_id` bigint unsigned DEFAULT NULL,
  `aggregate_type` varchar(60) NOT NULL,
  `aggregate_ref` binary(16) DEFAULT NULL,
  `event_type` varchar(80) NOT NULL,
  `payload` json NOT NULL,
  `rooms` json DEFAULT NULL,
  `status` enum('PENDING','DISPATCHED','DEAD') NOT NULL DEFAULT 'PENDING',
  `attempts` smallint unsigned NOT NULL DEFAULT '0',
  `available_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  `last_error` varchar(500) DEFAULT NULL,
  `correlation_id` binary(16) NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  `dispatched_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_outbox__event_id` (`event_id`),
  KEY `ix_outbox__status_available_id` (`status`,`available_at`,`id`),
  KEY `ix_outbox__status_dispatched` (`status`,`dispatched_at`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

