--
-- Table structure for table `pii_correction_requests`
--

DROP TABLE IF EXISTS `pii_correction_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pii_correction_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` binary(16) NOT NULL,
  `account_id` bigint unsigned DEFAULT NULL,
  `profile_id` bigint unsigned DEFAULT NULL,
  `institution_id` bigint unsigned DEFAULT NULL,
  `field` enum('FULL_NAME','DOB','GENDER','PAN','ID_NUMBER','ADMISSION_NO','EMPLOYEE_NO') NOT NULL,
  `current_masked` varchar(160) NOT NULL,
  `proposed_enc` varbinary(1024) NOT NULL,
  `reason` varchar(300) NOT NULL,
  `evidence_file_id` bigint unsigned NOT NULL,
  `approval_request_id` bigint unsigned NOT NULL,
  `applied_at` datetime(3) DEFAULT NULL,
  `closed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  `open_key` varchar(48) GENERATED ALWAYS AS (if(((`applied_at` is null) and (`closed_at` is null)),if((`profile_id` is null),concat(_utf8mb4'a',`account_id`,_utf8mb4':',`field`),concat(_utf8mb4'p',`profile_id`,_utf8mb4':',`field`)),NULL)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_pii_correction_requests__public_id` (`public_id`),
  UNIQUE KEY `ux_pii_correction_requests__open` (`open_key`),
