  CONSTRAINT `fk_role_change_log__operator` FOREIGN KEY (`operator_account_id`) REFERENCES `operator_accounts` (`id`),
  CONSTRAINT `fk_role_change_log__role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
