INSERT INTO `translations` VALUES ('hi','ACA.ALREADY_ENROLLED','यह छात्र {year} में पहले से नामांकित है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ALREADY_SUBMITTED','यह गृहकार्य पहले ही जमा किया जा चुका है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ASSIGNMENT_EXISTS','{name} पहले से {section} को {subject} पढ़ाते हैं।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ASSIGNMENT_NOT_FOUND','नियुक्ति नहीं मिली।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ASSIGNMENT_TIMETABLED','इस शिक्षक के {section} में {subject} के पीरियड हैं। पहले उन्हें किसी दूसरे शिक्षक को दें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.BREAK_PERIOD','अवकाश के समय कोई पाठ नहीं रखा जा सकता।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_AUDIENCE','यह प्रविष्टि किसके लिए है, चुनें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_DATES','समाप्ति तिथि आरंभ तिथि से पहले नहीं हो सकती।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_DUPLICATE','{title} पहले से {date} को कैलेंडर में है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_REPEAT','दोहराव आरंभ तिथि को या उसके बाद, वर्ष के भीतर समाप्त होना चाहिए।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_TIMES','समाप्ति समय आरंभ समय के बाद होना चाहिए।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_TITLE','3 से 80 अक्षरों का शीर्षक दर्ज करें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CAL_TYPE','एक प्रकार चुनें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CLASS_NAME_TAKEN','इस नाम की दूसरी कक्षा पहले से मौजूद है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CLASS_TEACHER_ONE_CLASS','{name} पहले से {year} के लिए {section} के कक्षा शिक्षक हैं। एक शिक्षक केवल एक ही कक्षा के कक्षा शिक्षक हो सकते हैं।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CLASS_TEACHER_ONLY','इसका निर्णय केवल कक्षा शिक्षक कर सकते हैं।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CLASS_TEACHER_TAKEN','{section} के लिए {year} में पहले से कक्षा शिक्षक हैं ({name})।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CLASSWORK_DUE','कक्षा कार्य की अंतिम तिथि बीता हुआ दिन नहीं हो सकती।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.COORDINATOR_REVIEW_REQUIRED','प्रधानाचार्य की समीक्षा से पहले समन्वयक को छुट्टी स्वीकृत करनी होगी।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.CORRECTION_PENDING','इस नामांकन का सुधार स्वीकृति की प्रतीक्षा में है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.DATE_OUTSIDE_YEAR','{label} ({from} – {to}) के भीतर की तिथि चुनें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.DECISION_REMARKS','कारण {min} से {max} अक्षरों में बताएँ।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.DUE_IN_PAST','गृहकार्य की अंतिम तिथि आज के बाद होनी चाहिए।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ENROLMENT_NOT_FOUND','नामांकन नहीं मिला।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.ENTRY_NOT_FOUND','कैलेंडर प्रविष्टि नहीं मिली।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_EXISTS','{year} में {section} के {subject} के लिए {exam} पहले से मौजूद है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_HAS_MARKS','इस परीक्षा के अंक पहले ही दर्ज हैं, इसलिए इसके अंक और स्थिति नहीं बदल सकते।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_MARKS_RANGE','अधिकतम अंक (1 से 1,000) और उत्तीर्ण अंक दर्ज करें जो अधिकतम से अधिक न हों।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_NAME','3 से 40 अक्षरों का परीक्षा नाम दर्ज करें।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_NAME_TAKEN','{name} पहले से मौजूद है।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_NOT_FOUND','परीक्षा नहीं मिली।','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.270'),('hi','ACA.EXAM_NOT_HELD','{date} को परीक