INSERT INTO `translations` VALUES ('kn','ui.web.x.461720bf41','ಶೈಕ್ಷಣಿಕ ವರ್ಷ ಆಯ್ಕೆಮಾಡಿ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.461bd12124','ಕೂಪನ್ ಪ್ರಕಾರವಾರು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.462062d37a','{0} ಅವರ ಕಾರ್ಡ್ ಮರುಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.462112da86','ಕೂಪನ್ ಆಯ್ಕೆಮಾಡಿ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4622277a19','10 ಅಂಕಿಯ ಮೊಬೈಲ್','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4635ed8525','ಪ್ರಕಾರ ಉಳಿಸಿ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46365ab4f5','{2} ಗಾಗಿ {0} {1}','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4639bcb18e','ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ GST ಸೇರಿದೆಯೇ?','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.463fb6496f','ಆ ದಿನ ವರ್ಗಾವಣೆ ಚಲಿಸಲಿಲ್ಲ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.464ba84215','ಪೂರ್ತಿ ಪಾವತಿಸಲಾಗಿದೆ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.464db4e54b','ಆನ್‌ಬೋರ್ಡಿಂಗ್: {1} ರಲ್ಲಿ {0} ಪೂರ್ಣಗೊಂಡಿದೆ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.464f2b826f','QR ಕಾರ್ಡ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.464f838e36','ಶುಭೋದಯ, {0}','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.465681c687','ವಿವಾದಿತ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.466fda21da','ಹೆಸರು ಮತ್ತು ವಿಳಾಸ ಒಟ್ಟಾಗಿ CampusOne ನಲ್ಲಿ ಅನನ್ಯವಾಗಿರಬೇಕು (FR-INS-01).','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.467b1521f8','ನಿಷ್ಕ್ರಿಯ ಕಾರ್ಡ್ ಇದೆ (','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4688afa7d1','— ಶಾಲೆ ಬಿಟ್ಟಿದ್ದಾರೆ ಅಥವಾ ಆಡಳಿತಾತ್ಮಕವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. ಸೈನ್ ಇನ್ ಮಾಡಲು, ಪಾವತಿಸಲು ಅಥವಾ ಹಣ ಪಡೆಯಲು ಸಾಧ್ಯವಿಲ್ಲ; ಪ್ರಸ್ತುತ ತರಗತಿ ಪಟ್ಟಿಗಳಿಂದ ತೆಗೆಯಲಾಗುತ್ತದೆ.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4698e431f4','ಪ್ರತಿ ಸಕ್ರಿಯ ವಿದ್ಯಾರ್ಥಿಯೂ {0} ರಲ್ಲಿ ದಾಖಲಾಗಿದ್ದಾರೆ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46997cc1e0','{0} ಟ್ರಿಪ್‌ಗಳು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46999d3298','ಎಲ್ಲಾ ಪರೀಕ್ಷೆಯ ಹೆಸರುಗಳು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46a2992153','ಹಿಂದಿನ ತಿಂಗಳು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46a422f6bb','ನಿಮ್ಮ ಪಾತ್ರದೊಂದಿಗೆ ವಿದ್ಯಾರ್ಥಿ ಬಳಕೆದಾರ ಪ್ರಕಾರಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ಈ ಅರ್ಜಿಯನ್ನು ಇಲ್ಲಿ ಅನುಮೋದಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46a448d46a','ಸ್ವತ್ತುಗಳನ್ನು ಸಂಸ್ಥೆಯ ನಿರ್ವಾಹಕರು ನಿರ್ವಹಿಸುತ್ತಾರೆ. ನಿಮ್ಮ ಪಾತ್ರ ತೆರೆಯಬಹುದಾದ ಪುಟಗಳನ್ನು ಮೆನುವಿನಲ್ಲಿ ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46a7e3ad70','ಎಕ್ಸ್‌ಪೋರ್ಟ್ ಆರಂಭವಾಗಿಲ್ಲ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46d4436623','ಈ ಪೀರಿಯಡ್‌ಗೆ ನಿಮ್ಮ ಹಾಜರಾತಿ ಗುರುತಿಸಲಾಗಿದೆ.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46d581d8d7','ಅನುಮೋದಿಸಿದರೆ ಪ್ರದರ್ಶನಕ್ಕೆ ಮಾತ್ರ ಇರುವ ಫೀಲ್ಡ್ ನವೀಕರಿಸಲ್ಪಡುತ್ತದೆ ಮತ್ತು ತಿದ್ದುಪಡಿಯನ್ನು ಸದಸ್ಯರ ಇತಿಹಾಸದಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ (CR-06).','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46f2a00ef5','ಎಲ್ಲಾ ಪರೀಕ್ಷೆಗಳು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46f7de357b','ನಿಲ್ದಾಣವಾರು ಶುಲ್ಕ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.46fea7cb01','ತಂದೆ ಮತ್ತು ತಾಯಿಯ ವಿವರಗಳು, ಪಾಲಕರಿದ್ದರೆ ಅವರದು, ಮತ್ತು ಶಾಲೆ ಮೊದಲು ಯಾರನ್ನು ಸಂಪರ್ಕಿಸಬೇಕು.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.47016b9f04','ಗೇಟ್ ಹಾಜರಾತಿ · ವಿದ್ಯಾರ್ಥಿಗಳು','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.4706583df9','ವಿವರಗಳನ್ನು ಉಳಿಸಿ','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.47072656c4','ಧನ್ಯವಾದಗಳು. ಈ ಸಂಖ್ಯೆಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳಿ — ಮೊಬೈಲ್ {0} ಜೊತೆಗೆ ಇದರಿಂದ ಅರ್ಜಿಯ ಸ್ಥಿತಿ ತಿಳಿಯಬಹುದು.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:37.056'),('kn','ui.web.x.470924f245','ಇನ್ನೂ ಟೋಕನ್ ವಿನಂತಿಗಳಿಲ್ಲ','MACHINE',NULL,NULL,0