INSERT INTO `translations` VALUES ('ml','ACA.LEAVE_BALANCE','{type} അവധിയുടെ {left} ദിവസം മാത്രമേ ബാക്കിയുള്ളൂ.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_DATES','അവസാന ദിവസം ആദ്യ ദിവസത്തിന് മുമ്പാകരുത്.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_NOT_FOUND','അവധി അപേക്ഷ കണ്ടെത്തിയില്ല.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_NOT_PENDING','ഈ അപേക്ഷയിൽ ഇതിനകം തീരുമാനമെടുത്തു അല്ലെങ്കിൽ പിൻവലിച്ചു.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_OVERLAP','{name}-ന് {dates}-ന് ഇതിനകം അവധി അപേക്ഷയുണ്ട് ({ref}, {status}). മറ്റ് തീയതികൾ തിരഞ്ഞെടുക്കുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_PAST','അവധി കഴിഞ്ഞ ദിവസം ആരംഭിക്കാനാവില്ല.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_REASON','കാരണം {min} മുതൽ {max} വരെ അക്ഷരങ്ങളിൽ എഴുതുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.LEAVE_TYPE','അവധിയുടെ തരം തിരഞ്ഞെടുക്കുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.MARK_NOT_ENROLLED','വരി {n}: വിദ്യാർത്ഥി {year}-ലേക്ക് {section}-ൽ ചേർന്നിട്ടില്ല.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.MARK_RANGE','വരി {n}: 0 മുതൽ {max} വരെ പൂർണ്ണമോ പകുതിയോ മാർക്ക്, ഹാജരില്ലാത്തവർക്ക് AB നൽകുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.MARKS_INCOMPLETE','{n} വിദ്യാർത്ഥികൾക്ക് ഇനിയും മാർക്കില്ല. പ്രസിദ്ധീകരിക്കും മുമ്പ് ഓരോ വിദ്യാർത്ഥിക്കും മാർക്ക് അല്ലെങ്കിൽ AB നൽകുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.NEXT_YEAR_NEEDED','അടുത്ത വർഷത്തിലേക്ക് മാറ്റും മുമ്പ് അടുത്ത അധ്യയന വർഷം ചേർക്കുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.NO_CURRENT_YEAR','ആദ്യം നിലവിലെ അധ്യയന വർഷം സജ്ജീകരിക്കുക.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.NON_SCHOOL_DAYS','ആ ദിവസങ്ങൾ ഞായറാഴ്ചകളോ സ്കൂൾ അവധികളോ ആണ് — അവധി ആവശ്യമില്ല.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.641'),('ml','ACA.NOT_A_STUDENT','സ്ഥാപനത്തിലെ സജീവ വിദ്യാർത്ഥിയെ തിരഞ്ഞെടുക