INSERT INTO `translations` VALUES ('ta','ui.web.x.2d5f672d8d','செலுத்துபவர் எப்படிச் செலுத்துகிறார்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d701d3297','குறிக்கப்படவில்லை · ஊதியத்திற்கு முன் சரிபார்க்கவும்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d70b97f0e','எந்தக் கூப்பனும் பயன்படுத்தப்படவில்லை.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d7219a662','தற்போதைய இணைப்பும் QR-உம் உடனே வேலை செய்வது நின்றுவிடும்; அவற்றைத் திறப்பவர்கள் புதியதைப் பள்ளியிடம் கேட்கும்படி ஒரு குறிப்பைப் பார்ப்பார்கள். ஏற்கெனவே தொடங்கிய வரைவுகள் வைக்கப்பட்டு, தொடரப்படலாம்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d7434939b','ரசீது எண்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d746c8c98','{0} {1} ‘வரவில்லை’ எனக் குறிக்கப்படுவார்கள்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d7bf67d43','உறுப்பினர்கள் இல்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d7df06635','ஒவ்வொரு ஓட்டமும் அதன் தூண்டல், நிலை, எண்ணிக்கைகளுடன் இங்கே தோன்றும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d7fe9547f','நிலை & வாலெட்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2d8dc9325a','{0}-க்கு இன்னும் திட்டம் இல்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2da0e2fd46','முடிக்கப்படவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2da600bf94','பதிப்பு','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2da751dbd4','நீக்கும் வசதி இல்லை: வெளியேறும் உறுப்பினரின் இணைப்பு நீக்கப்பட்டு அவர் ‘செயலில் இல்லை’ ஆகிவிடுவார்; பதிவு, வாலெட் பேரேடு, வரலாறு வைக்கப்படும் (CR-08). வகுப்புகளும் பிரிவுகளும் {0}-க்கானவை (CR-13).','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dbc2fd235','ஆன்லைன்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dbd6558ff','தட்டல்கள் சாதனத்தில் வரிசைப்படுத்தப்பட்டு, மீண்டும் இணைந்ததும் அனுப்பப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dbee1b18c','நிறுவனங்களை ஏற்ற முடியவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dbf73acf3','அனைத்துப் பிரிவுகளும்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dc4547bfe','குறிப்புகள் எதுவும் கொடுக்கப்படவில்லை.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ddef5dcc0','கட்-ஆஃப் நேரத்தில் தானியங்கி ‘வரவில்லை’','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2de1bd35bc','புதிய கார்டு அங்கீகரிக்கப்பட்டது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2de26351cd','Key சீக்ரெட்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2de366fad2','CSV ஏற்றுமதி தயார் · {0}','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2de43d2e2d','இன்று கிடைக்காது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2de7515c36','முதன்மைத் தொடர்பாளரின் மின்னஞ்சல்: பள்ளியும் இங்கே எழுதும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2df2dd29d7','QR குறியீட்டைக் காட்டு','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2df47c5549','ஆர்டர்களும் கார்டு தட்டல்களும் இந்தக் கவுண்டரில் சேமிக்கப்பட்டு, இணைப்பு திரும்பியதும் ஒருமுறை அனுப்பப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2df7120c2e','முடிவுக்காக எதுவும் காத்திருக்கவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dfcf898a3','ஒப்பீடு','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2dfdf17bbd','கடவுச்சொற்கள் நகலெடுக்கப்பட்டன','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e00359b98','சமர்ப்பிக்கப்பட்டது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e00c4e537','{0} நிமிடங்களுக்குள் சாதனத்தில் இணைப்புக் குறியீட்டை உள்ளிடவும்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e02623966','தொடர்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e0b6667af','கட்டணப் பதிவுகள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e12218793','CampusOne இதை அமைத்துக்கொண்டிருக்கிறது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e18ccc097','இருப்புக்காகக் காத்திருக்கிறது.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e1940af7c','வழித்தடங்கள், நேரலைப் பயணங்கள், பெற்றோருக்கான நிறுத்த வாரியான எச்சரிக்கைகள்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e3133603f','மாணவர்களையும் குறைந்தது ஒரு கூப்பன் வகையையும் தேர்ந்தெடுக்கவும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e33026b74','புகார்களைப் புகார் அலுவலர் கையாள்வார். உங்கள் பொறுப்பால் திறக்கக்கூடிய பக்கங்கள் மெனுவில் பட்டியலிடப்பட்டுள்ளன.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e341d91e0','{0} உடனே மீண்டும் கன்சோலில் உள்நுழையலாம். பூட்டு நீக்கமும் உங்கள் காரணமும் பதிவுசெய்யப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e3d483bf9','உறுதிமொழி இன்னும் ஏற்கப்படவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e43b8cc27','வணிகர் பதிவுசெய்யப்பட்டார்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e46745daf','{0} வெளியிடப்பட்ட கேள்விகள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e48295b34','படித்தொகையை ரத்துசெய்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e4c8606ef','செலுத்த வேண்டிய சேர்க்கைக் கட்டணங்கள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e6c4d1dc2','நிர்வாகக் குழு நிர்வாகப் பார்வைகளைப் படிக்க மட்டுமே முடியும். ஒப்புதல்கள் மீதான முடிவுகள் ஒப்புதல் வரிசையில் உங்கள் பெயரில் பதிவுசெய்யப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e80b24554','{1}-ஐக் குறிப்பிட்டு {0} பேரேட்டுப் பணத்திருப்பத்தைப் பதிவுசெய்யும் — {2} {3}-க்குத் திருப்பிச் செலுத்தும் — செலுத்துபவருக்கும் தெரிவிக்கும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e8a57cc5c','இணையதளம்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e8e5efc1b','அடுத்து, உங்கள் மொபைலுக்கு ஒருமுறைக் குறியீட்டை அனுப்புவோம்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e8f7c3bd1','தயாரிப்பாளர்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e905a3451','ஒவ்வொரு நிறுவனத்தின் அடுத்த புதுப்பிப்பிலிருந்து பொருந்தும்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e953a7548','{0} · {1} தொகுதிகள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2e95a53add','ரத்துசெய்த பிறகு, தக்கவைப்புக் காலத்தின் இறுதியில் தரவு நீக்கப்படும்; அந்தக் காலம் இன்னும் ஒப்புக்கொள்ளப்படவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2eb0c3b72a','வகுப்பு உயர்வு பெற்றவர்கள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2eb509ccf0','{0}-க்குப் பாட ஆசிரியர் ஒதுக்கீடுகள் இல்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ebb869edb','வசூலானது · {0}','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ebd435f4b','{0}-இன் ஆதார் · PAN','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ebde1e3b4','இது ‘விண்ணப்பங்கள்’ பக்கத்தில் திறக்கும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ebf43e6ee','{0} இன்னும் தொடங்கவில்லை.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ec4a97223','செயல்படுத்தும்போது, புதுப்பிக்கும்போது, திட்டத்தை மேம்படுத்தும்போது (விகிதாசாரமாக), சுழற்சியின் இறுதியில் திட்ட ஒதுக்கீட்டுக்கு மேலான பயன்பாட்டுக்கு விலைப்பட்டியல்கள் வழங்கப்படும்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ec5d7386b','கார்டு முடக்கப்பட்டது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ece56bcb7','கார்டு தட்டலைக் கேள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ed08dd9d3','விகிதத்தை மாற்றினால் ஏற்கெனவே விதிக்கப்பட்ட நிலுவைகள் மாறாது. தொலைவான நிறுத்தத்திற்கு மாறினால் மீதமுள்ள மாதங்களுக்கு விதிக்கப்படும்; அருகிலுள்ள நிறுத்தத்திற்கு மாறினால் அந்த ஆண்டுக்கு எதுவும் மாறாது.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ee3f18c28','“{0}”-க்கான டிக்கெட்டுகள் · {1}','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ee6ffa098','வருகைப் பதிவு & பிற','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2ef92db05b','வேறொரு சொல்லை முயலவும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2efd0a1b95','நிலை 1','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f05bc55e9','பின்னர் அனுப்பு','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f111a7d0f','{0} வணிகர்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f18e7ab3e','{0}-க்கான சொத்துக் குழுக்கள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f1a103b2e','மதிப்பெண்களைச் சரிபார்க்க முடியவில்லை','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f3fccb769','சோதனைக் காலம் மாறும்போது CampusOne திட்டத்தைச் செயல்படுத்தும்; அப்போது முதல் சுழற்சிக்குக் கட்டணம் விதிக்கப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f4b8c566b','ஆபரேட்டர் மொபைல்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f5423cbda','பள்ளியின் பேமெண்ட் கேட்வே இன்னும் இணைக்கப்படவில்லை, எனவே பணம் எதுவும் நகராது: சோதனையாக {0} செலுத்தப்பட்டதாகக் குறிக்கப்படும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f5ad64949','இணைப்புக்காகக் காத்திருக்கிறது','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f5d24c330','உங்கள் பொறுப்புக்கான எச்சரிக்கைகள் இங்கே தோன்றும்.','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f65d45b44','இணைப்பு நீக்க, வளாக வாலெட் இருப்பு பூஜ்ஜியமாக இருக்க வேண்டும் (BR-19). உறுப்பினர்கள் ஒருபோதும் நீக்கப்படுவதில்லை — சுயவிவரம் ‘செயலில் இல்லை’, ‘இணைக்கப்படவில்லை’ ஆகிவிடும் (CR-08).','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f68195d13','கட்டண அமைப்புகள்','MACHINE',NULL,NULL,0,'2026-11-02 09:33:38.421'),('ta','ui.web.x.2f682389