DROP TABLE IF EXISTS `ledger_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ledger_accounts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `institution_id` bigint unsigned DEFAULT NULL,
  `kind` enum('WALLET','BANK_POOL','PAYOUT_CLEARING','PLATFORM_FEE','HELD_SUSPENSE','REFUND_CLEARING','CHARGEBACK_CLEARING','COUPON_REIMBURSEMENT','ADJUSTMENT','ALLOWANCE_FUNDING') NOT NULL,
  `wallet_id` bigint unsigned DEFAULT NULL,
  `name` varchar(80) NOT NULL,
  `scope_key` varchar(48) GENERATED ALWAYS AS (concat(coalesce(`institution_id`,0),_utf8mb4':',`kind`,_utf8mb4':',coalesce(`wallet_id`,0))) STORED,
  `created_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_ledger_accounts__scope` (`scope_key`),
  UNIQUE KEY `ux_ledger_accounts__wallet` (`wallet_id`),
  KEY `fk_ledger_accounts__institution` (`institution_id`),
  CONSTRAINT `fk_ledger_accounts__institution` FOREIGN KEY (`institution_id`) REFERENCES `institutions` (`id`),
  CONSTRAINT `fk_ledger_accounts__wallet` FOREIGN KEY (`wallet_id`) REFERENCES `wallets` (`id`),
  CONSTRAINT `ck_ledger_accounts__wallet` CHECK (((`kind` = _utf8mb4'WALLET') = (`wallet_id` is not null)))
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
