CREATE TABLE `ledger_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `posted_on` date NOT NULL,
  `public_id` binary(16) NOT NULL,
  `institution_id` bigint unsigned DEFAULT NULL,
  `reference` char(35) NOT NULL,
  `type` enum('PAYMENT','TRANSFER','BANK_CREDIT','TUITION','ALLOWANCE_CREDIT','ALLOWANCE_PAYMENT','COUPON_REDEMPTION','EVENT','REFUND','REVERSAL','CHARGEBACK','SETTLEMENT_PAYOUT','PLATFORM_FEE','ADJUSTMENT','HOLD_RELEASE','ALLOWANCE_EXPIRY') NOT NULL,
  `channel` varchar(24) NOT NULL,
  `amount_paise` bigint unsigned NOT NULL,
  `idempotency_key` varchar(100) NOT NULL,
  `business_ref_type` varchar(40) DEFAULT NULL,
  `business_ref_id` bigint unsigned DEFAULT NULL,
  `reversal_of_txn_id` bigint unsigned DEFAULT NULL,
  `narration` varchar(140) DEFAULT NULL,
  `posted_at` datetime(3) NOT NULL,
  `actor_ref` binary(16) DEFAULT NULL,
  `correlation_id` binary(16) NOT NULL,
  PRIMARY KEY (`id`,`posted_on`),
  UNIQUE KEY `ux_ledger_txn__public_id` (`public_id`,`posted_on`),
  UNIQUE KEY `ux_ledger_txn__reference` (`reference`,`posted_on`),
  KEY `ix_ledger_txn__inst_posted` (`institution_id`,`posted_at`),
  KEY `ix_ledger_txn__inst_business` (`institution_id`,`business_ref_type`,`business_ref_id`),
  KEY `ix_ledger_txn__reversal` (`reversal_of_txn_id`),
  CONSTRAINT `ck_ledger_txn__amount` CHECK ((`amount_paise` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
