/*!50003 CREATE*/ /*!50017 DEFINER=`campusone_migrator`@`localhost`*/ /*!50003 TRIGGER `trg_member_profiles__seq` BEFORE INSERT ON `member_profiles` FOR EACH ROW BEGIN
  SET NEW.member_seq = IF(
    NEW.member_seq IS NULL OR NEW.member_seq = 0,
    (SELECT COALESCE(MAX(p.member_seq), 0) + 1 FROM member_profiles p WHERE p.institution_id = NEW.institution_id),
    NEW.member_seq
  );
END */;;
DELIMITER ;
