DROP TABLE IF EXISTS `payment_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `public_id` binary(16) NOT NULL,
  `institution_id` bigint unsigned NOT NULL,
  `merchant_profile_id` bigint unsigned NOT NULL,
  `kind` enum('DYNAMIC_QR','NFC') NOT NULL,
  `instrument` enum('WALLET','ALLOWANCE') NOT NULL DEFAULT 'WALLET',
  `order_id` bigint unsigned DEFAULT NULL,
  `terminal_id` bigint unsigned DEFAULT NULL,
  `api_client_id` bigint unsigned DEFAULT NULL,
  `amount_paise` bigint unsigned NOT NULL,
  `token` char(26) NOT NULL,
  `nonce_hash` binary(32) DEFAULT NULL,
  `status` enum('PENDING','SUCCESS','FAILED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `expires_at` datetime(3) NOT NULL,
  `consumed_at` datetime(3) DEFAULT NULL,
  `payer_profile_id` bigint unsigned DEFAULT NULL,
  `payment_attempt_id` bigint unsigned DEFAULT NULL,
  `failure_code` varchar(64) DEFAULT NULL,
  `created_by` binary(16) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT (utc_timestamp(3)),
  `row_version` int unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_payment_requests__public_id` (`public_id`),
  UNIQUE KEY `ux_payment_requests__token` (`token`),
  UNIQUE KEY `ux_payment_requests__nonce` (`nonce_hash`),
  KEY `ix_payment_requests__inst_merchant` (`institution_id`,`merchant_profile_id`,`status`,`expires_at`),
  KEY `fk_payment_requests__merchant` (`merchant_profile_id`),
  KEY `fk_payment_requests__payer` (`payer_profile_id`),
  KEY `fk_payment_requests__attempt` (`payment_attempt_id`),
  KEY `ix_payment_requests__order` (`order_id`,`status`),
  KEY `fk_payment_requests__terminal` (`terminal_id`),
  KEY `fk_payment_requests__client` (`api_client_id`),
  CONSTRAINT `fk_payment_requests__attempt` FOREIGN KEY (`payment_attempt_id`) REFERENCES `payment_attempts` (`id`),
  CONSTRAINT `fk_payment_requests__client` FOREIGN KEY (`api_client_id`) REFERENCES `campusone`.`api_clients` (`id`),
  CONSTRAINT `fk_payment_requests__institution` FOREIGN KEY (`institution_id`) REFERENCES `institutions` (`id`),
  CONSTRAINT `fk_payment_requests__merchant` FOREIGN KEY (`merchant_profile_id`) REFERENCES `merchants` (`profile_id`),
  CONSTRAINT `fk_payment_requests__order` FOREIGN KEY (`order_id`) REFERENCES `pos_orders` (`id`),
  CONSTRAINT `fk_payment_requests__payer` FOREIGN KEY (`payer_profile_id`) REFERENCES `member_profiles` (`id`),
  CONSTRAINT `fk_payment_requests__terminal` FOREIGN KEY (`terminal_id`) REFERENCES `terminals` (`id`),
  CONSTRAINT `ck_payment_requests__amount` CHECK ((`amount_paise` > 0)),
  CONSTRAINT `ck_payment_requests__nonce` CHECK (((`kind` = _utf8mb4'NFC') = (`nonce_hash` is not null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
